import type {
  BoardColumn,
  FlowEdge,
  FlowNode,
  FlowspaceDocument,
} from "../types.ts";
import { defaultBoardWithExamples, findBoardCard, formatBoardMarkdown, normalizeBoardColumns } from "./board.ts";
import { tFor, type Locale } from "./i18n.ts";
import { DEFAULT_FLOW_SIZE, descriptorOf, sizeOf } from "./nodes/registry.ts";

export function workflowNodes(document: FlowspaceDocument): FlowNode[] {
  return [
    ...document.nodes,
    ...(document.templates ?? []).flatMap((template) => template.nodes),
    ...(document.snapshots ?? []).flatMap((snapshot) => snapshot.nodes),
  ];
}

export const uid = (): string => crypto.randomUUID();

export const DEFAULT_AGENT_TITLES = new Set(["新 Agent", "New Agent", ""]);

function stripNullFields<T>(value: T, structuredContent = false): T {
  if (value === null || value === undefined || typeof value !== "object") {
    return value;
  }
  if (Array.isArray(value)) {
    const items = [];
    for (const item of value) {
      if (item != null) items.push(stripNullFields(item, structuredContent));
    }
    return items as T;
  }
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
    if (structuredContent && k === "value") {
      out[k] = structuredClone(v);
      continue;
    }
    if (v === null || v === undefined) continue;
    // Plugin JSON may use null as a value, including in arrays.
    out[k] = k === "config" && "kind" in value && value.kind === "flow"
      ? structuredClone(v) : stripNullFields(v, structuredContent || k === "snapshotContent");
  }
  return out as T;
}

/**
 * Strip `null` on optional document fields (`window: null`, `window.snap: null`, etc.)
 * before crossing the Typert wire boundary or storage validation.
 */
export function sanitizeDocumentForWire(
  doc: FlowspaceDocument,
): FlowspaceDocument {
  return stripNullFields(doc);
}

export function emptyDocument(): FlowspaceDocument {
  return {
    version: 1,
    id: "main",
    title: "FlowSpace",
    nodes: [],
    edges: [],
    viewport: { x: 0, y: 0, zoom: 1 },
    settings: { nativeChatTriggers: true, reducedMotion: false },
  };
}

export const DEFAULT_NODE_FULL_SIZE: Record<FlowNode["kind"], [number, number]> = {
  agent: [312, 392],
  note: [276, 200],
  file: [300, 286],
  display: [300, 252],
  group: [1152, 474],
  board: [580, 380],
  detail: [340, 362],
  git: [420, 410],
  changes: [360, 340],
  terminal: [380, 320],
  role: [260, 336],
  flow: DEFAULT_FLOW_SIZE.full,
};

export function boardSummaryText(
  columns: BoardColumn[],
  selectedIds?: string[],
): string {
  return formatBoardMarkdown(normalizeBoardColumns(columns), selectedIds);
}

export function referenceTitle(node: FlowNode | undefined, edge: FlowEdge): string {
  if (node?.kind === "board" && edge.sourceItemKey !== undefined) {
    return findBoardCard(node.columns ?? [], edge.sourceItemKey)?.card.text || node.title;
  }
  return edge.snapshotTitle || node?.title || edge.source;
}

/** Derive an auto-title from the first non-empty line of a draft prompt (D38). */
export function deriveDraftTitle(
  prompt: string,
  fallback = "新 Agent",
): string {
  const first = prompt
    .split(/\r?\n/)
    .map((line) => line.replace(/^[#>*\-\s]+/, "").trim())
    .find(Boolean);
  if (!first) return fallback;
  return first.length > 36 ? `${first.slice(0, 36)}…` : first;
}

/** Automatically derive a descriptive title for untitled Agent drafts once prompt text exists. */
export function syncUntitledAgentNode(node: FlowNode): boolean {
  if (node.kind !== "agent" || node.customTitle) return false;
  if (!DEFAULT_AGENT_TITLES.has(node.title.trim())) return false;
  const seed =
    node.draft.trim() ||
    node.task.trim() ||
    (node.continuationPrompt ?? "").trim();
  if (!seed) return false;
  const derived = deriveDraftTitle(seed, node.title || "新 Agent");
  if (derived && derived !== node.title) {
    node.title = derived;
    return true;
  }
  return false;
}

export function syncUntitledAgentTitles(doc: FlowspaceDocument): boolean {
  let changed = false;
  for (const node of doc.nodes) {
    if (syncUntitledAgentNode(node)) changed = true;
  }
  return changed;
}

export function newNode(
  kind: FlowNode["kind"],
  x: number,
  y: number,
  title?: string,
  locale: "zh" | "en" = "zh",
): FlowNode {
  const [width, height] = DEFAULT_NODE_FULL_SIZE[kind] ?? [312, 260];
  const columns = kind === "board" ? defaultBoardWithExamples(locale) : undefined;
  const isCustomTitle =
    Boolean(title) &&
    !(kind === "agent" && DEFAULT_AGENT_TITLES.has((title ?? "").trim()));
  return {
    id: uid(),
    kind,
    title:
      title ??
      {
        agent: "新 Agent",
        note: "便签",
        file: "文件引用",
        display: "展示结果",
        group: "工作流",
        board: locale === "en" ? "Task board" : "任务看板",
        detail: "执行详情",
        git: "Git 仓库",
        changes: "轮次改动",
        terminal: "终端快照",
        role: "新岗位",
        flow: tFor(locale, "flow_node"),
      }[kind],
    x,
    y,
    width,
    height,
    expanded:
      kind === "agent" ||
      kind === "note" ||
      kind === "display" ||
      kind === "board" ||
      kind === "detail" ||
      kind === "git" ||
      kind === "role" ||
      kind === "flow",
    task: "",
    draft: "",
    nativeTrigger: "inherit",
    participation: "global",
    text: columns ? boardSummaryText(columns) : "",
    fixed: kind !== "detail",
    collapsed: false,
    ...(isCustomTitle ? { customTitle: true } : {}),
    ...(kind === "agent"
      ? { tab: "task" as const, rerun: "change" as const }
      : {}),
    ...(kind === "file" ? { items: [], selectedItems: [] } : {}),
    ...(kind === "git" ? { gitTab: "changes" as const } : {}),
    ...(kind === "group" ? { color: "blue" as const, ports: [] } : {}),
    ...(columns ? { columns, selectedItems: [] } : {}),
  };
}
export function newFlowNode(flowType: string, x: number, y: number, locale: Locale = "zh"): FlowNode {
  const node = newNode("flow", x, y, undefined, locale);
  node.flowType = flowType;
  const descriptor = descriptorOf(flowType);
  if (descriptor) {
    node.titleKey = descriptor.titleKey;
    node.title = tFor(locale, node.titleKey);
    node.config = structuredClone(descriptor.defaultConfig);
    node.configVersion = descriptor.version;
    [node.width, node.height] = sizeOf(node, false);
  }
  return node;
}

export function newEdge(
  source: string,
  target: string,
  kind: FlowEdge["kind"],
): FlowEdge {
  return {
    id: uid(),
    source,
    target,
    kind,
    ...(kind === "event" ? { event: { mode: "end" as const, kinds: ["done" as const], cooldownMs: 1000, maxTimes: 10 } } : {}),
    mode: "conclusion",
    trigger: kind === "reference" ? "off" : "auto",
    maxRounds: 3,
    always: false,
    waypoints: [],
  };
}
export function members(doc: FlowspaceDocument, groupId: string): string[] {
  return doc.nodes
    .filter((n) => n.parentId === groupId)
    .flatMap((n) => (n.kind === "group" ? members(doc, n.id) : [n.id]));
}
export function groupDescendants(
  doc: FlowspaceDocument,
  groupId: string,
): string[] {
  return doc.nodes
    .filter((n) => n.parentId === groupId)
    .flatMap((n) => [
      n.id,
      ...(n.kind === "group" ? groupDescendants(doc, n.id) : []),
    ]);
}
export function sample(
  doc: FlowspaceDocument,
  kind: "review" | "parallel",
  placement?: { workspaceId?: string; cwd?: string },
  availableFiles?: string[],
): FlowspaceDocument {
  const copy = structuredClone(doc);
  const baseX = copy.nodes.length
    ? Math.max(...copy.nodes.map((n) => n.x + n.width)) + 132
    : 40;
  const baseY = 194;
  const group = {
    ...newNode(
      "group",
      baseX - 24,
      baseY - 54,
      kind === "review" ? "分析与审查工作流" : "并行调查工作流",
    ),
    color: (kind === "review" ? "blue" : "teal") as "blue" | "teal",
    width: kind === "review" ? 1152 : 756,
    height: 474,
  };
  const prompts =
    kind === "review"
      ? [
          [
            "分析项目",
            "阅读当前工作区，简要说明项目用途、核心架构与最值得改进的一点。先不要修改文件。",
            "implementation",
            true,
          ],
          [
            "审查建议",
            "审查上游建议的可行性，核对证据、边界风险与不足。先不要修改文件。",
            "review",
            true,
          ],
          [
            "汇总结论",
            "结合上游审查结论，给出结构清晰、可执行的行动清单。",
            "delivery",
            true,
          ],
        ]
      : [
          [
            "探索架构",
            "阅读工作区，概括整体架构、核心模块与数据流。不要修改文件。",
            "implementation",
            false,
          ],
          [
            "调查验证",
            "阅读工作区，概括测试覆盖、类型检查与集成验证方式。不要修改文件。",
            "implementation",
            false,
          ],
          [
            "汇总结论",
            "等两路调查完成，综合整理出一份有明确下一步建议的项目概览。",
            "review",
            true,
          ],
        ];
  const nodes = prompts.map(([title, task, roleLabel, full], i) => ({
    ...newNode(
      "agent",
      baseX + (kind === "parallel" ? (i === 2 ? 396 : 0) : i * 396),
      kind === "parallel"
        ? i === 0
          ? baseY + 12
          : i === 1
            ? baseY + 214
            : baseY
        : baseY,
      title as string,
    ),
    ...placement,
    parentId: group.id,
    expanded: full as boolean,
    roleLabel: roleLabel as string,
    task: task as string,
    draft: task as string,
    continuationPrompt: i > 0 ? (task as string) : undefined,
  }));
  const fileItems = availableFiles ? availableFiles.slice(0, 4) : [];
  const firstFile = fileItems[0] ?? "";
  const fileCard = {
    ...newNode("file", baseX, baseY - 146, "工作区文件"),
    ...placement,
    items: fileItems,
    selectedItems: firstFile ? [firstFile] : [],
    text: firstFile,
    expanded: false,
    pinned: true,
  };
  const note = {
    ...newNode(
      "note",
      baseX + (kind === "review" ? 460 : 300),
      baseY - 160,
      "验收标准",
    ),
    text: "先只读核对代码事实，保持结论精炼可验证；确认无误后再放行整理交付清单。",
    expanded: false,
    pinned: true,
  };
  const edges =
    kind === "review"
      ? [
          newEdge(nodes[0].id, nodes[1].id, "continuation"),
          {
            ...newEdge(nodes[1].id, nodes[2].id, "continuation"),
            trigger: "confirm" as const,
          },
          ...(firstFile
            ? [newEdge(fileCard.id, nodes[1].id, "reference")]
            : [newEdge(note.id, nodes[1].id, "reference")]),
          newEdge(note.id, nodes[2].id, "reference"),
        ]
      : [
          newEdge(nodes[0].id, nodes[2].id, "continuation"),
          newEdge(nodes[1].id, nodes[2].id, "continuation"),
          ...(firstFile
            ? [newEdge(fileCard.id, nodes[0].id, "reference")]
            : []),
          newEdge(note.id, nodes[2].id, "reference"),
        ];
  copy.nodes.push(group, fileCard, note, ...nodes);
  copy.edges.push(...edges);
  return copy;
}
